const cmd = `$env:Path='C:\\Windows\\System32;'+$env:Path
$ua='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/155.0.0.0 Safari/537.36'
$u='https://talk.collegeconfidential.com/search.json?q=%22essay%20editing%22'
$code = curl.exe -s -o "$env:TEMP\\cc.json" -w "%{http_code} %{size_download}" -x http://127.0.0.1:7897 -H "User-Agent: $ua" --max-time 40 --compressed $u
Write-Output "== $code"
$j = Get-Content "$env:TEMP\\cc.json" -Raw | ConvertFrom-Json
Write-Output ("posts=" + $j.posts.Count + " topics=" + $j.topics.Count)
$j.posts | Select-Object -First 8 | ForEach-Object { Write-Output ("--- " + $_.created_at + " | " + $_.username + " | topic " + $_.topic_id); Write-Output ("    " + $_.blurb) }`;
const r = await tools.pwsh({ description: "Probe CC Discourse search", command: cmd, timeoutMs: 120000 });
console.log(r.kind === 'foreground' ? r.stdout.text + "|ERR:" + r.stderr.text : JSON.stringify(r));
